# Runs inside the (same-origin) components iframe on EVERY render: binds ONE delegated click listener on the parent page (open/close,
# open by default on the first visit) and scrolls the message area to the newest message (Streamlit does not do that by itself).
WIDGET_JS = """
<script>
(function () {
  const w = window.parent, d = w.document;
  if (!w.__tixBound) {
    w.__tixBound = true;
    try { if (w.sessionStorage.getItem('tixOpen') !== '0') d.body.classList.add('tix-open'); } catch (e) { d.body.classList.add('tix-open'); }
    d.addEventListener('input', function (e) {
      if (e.target.id !== 'tix-store-search') return;
      const query = e.target.value.trim();
      let found = 0;
      d.querySelectorAll('.store-tile[data-category]').forEach(function (tile) {
        tile.hidden = !tile.dataset.category.includes(query);
        if (!tile.hidden) found++;
      });
      const empty = d.getElementById('tix-store-empty');
      if (empty) empty.hidden = found !== 0;
    });
    d.addEventListener('click', function (e) {
      if (e.target.closest('[data-tix-open]')) d.body.classList.add('tix-open');
      else if (e.target.closest('#tix-fab')) d.body.classList.toggle('tix-open');
      else if (e.target.closest('#tix-close')) d.body.classList.remove('tix-open');
      else return;
      try { w.sessionStorage.setItem('tixOpen', d.body.classList.contains('tix-open') ? '1' : '0'); } catch (err) {}
    });
  }
  const fit = function () {
    const v = w.visualViewport;
    d.documentElement.style.setProperty('--tix-view-height', (v ? v.height : w.innerHeight) + 'px');
    d.documentElement.style.setProperty('--tix-view-top', (v ? v.offsetTop : 0) + 'px');
  };
  fit();
  if (!w.__tixViewportBound) {
    w.__tixViewportBound = true;
    w.addEventListener('resize', fit);
    if (w.visualViewport) {
      w.visualViewport.addEventListener('resize', fit);
      w.visualViewport.addEventListener('scroll', fit);
    }
  }
  const down = function () {
    const box = d.querySelector('.st-key-chat_msgs');
    if (!box) return;
    const el = [box].concat(Array.from(box.querySelectorAll('div'))).find(function (n) {
      return n.scrollHeight > n.clientHeight + 4 && w.getComputedStyle(n).overflowY !== 'visible'; });
    if (el) el.scrollTop = el.scrollHeight;
  };
  setTimeout(down, 60); setTimeout(down, 400);
})();
</script>
"""